'use strict';

/*
 * HTTP function POST /api/bypass (Azure Static Web Apps, managed functions, programming model v4).
 * All the logic is in ../lib/bypass-handler.js; this file reads the configuration and adapts the request.
 *
 * Configuration:
 *   api/config.json          generated by tools/prepare-api.js from the environment file (tenantId,
 *                            clientId, authContext, justification limits); no secret;
 *   NFM_RECEIPT_KEY          application setting (secret): base64 of at least 32 bytes;
 *   APPLICATIONINSIGHTS_CONNECTION_STRING   (optional) context.log entries become traces.
 */
const fs = require('node:fs');
const path = require('node:path');
const { app } = require('@azure/functions');
const { handleBypass } = require('../lib/bypass-handler');
const { remoteKeyResolver } = require('../lib/token');

let cachedConfig;
let cachedResolver;

function loadConfig() {
  if (cachedConfig === undefined) {
    try {
      cachedConfig = JSON.parse(fs.readFileSync(path.join(__dirname, '..', '..', 'config.json'), 'utf8'));
    } catch (e) {
      cachedConfig = null;
    }
  }
  return cachedConfig;
}

function keyResolver(config) {
  if (!cachedResolver) {
    cachedResolver = remoteKeyResolver(config.tenantId);
  }
  return cachedResolver;
}

app.http('bypass', {
  methods: ['POST', 'GET'],
  authLevel: 'anonymous', // authentication is the Entra token, validated by handleBypass
  route: 'bypass',
  handler: async (request, context) => {
    const config = loadConfig();
    let body;
    if (request.method === 'POST') {
      try {
        body = await request.json();
      } catch (e) {
        body = undefined;
      }
    }
    const result = await handleBypass(
      {
        method: request.method,
        // The Entra token travels in X-NFM-Token: Static Web Apps replaces Authorization with its internal token.
        tokenHeader: request.headers.get('x-nfm-token'),
        authorization: request.headers.get('authorization'),
        userAgent: request.headers.get('user-agent'),
        clientIp: (request.headers.get('x-forwarded-for') || request.headers.get('x-azure-clientip') || '').split(',')[0].trim() || null,
        body
      },
      {
        config,
        keyResolver: config && config.tenantId ? keyResolver(config) : undefined,
        receiptKey: process.env.NFM_RECEIPT_KEY,
        log: (line) => context.log(line)
      }
    );
    return { status: result.status, headers: result.headers, jsonBody: result.body };
  }
});
